def find_median(a, b):
    # Search the shorter array so the forced cut j always lands inside b.
    if len(a) > len(b):
        a, b = b, a

    n, m = len(a), len(b)
    half = (n + m + 1) // 2      # +1 leaves the odd extra on the left
    low, high = 0, n             # inclusive: cutting at either end is legal

    while low <= high:
        i = (low + high) // 2    # a[:i] goes left
        j = half - i             # forced by the half-size rule

        # Sentinels remove every empty-array and end-of-array special case.
        a_left = a[i - 1] if i > 0 else float('-inf')
        a_right = a[i] if i < n else float('inf')
        b_left = b[j - 1] if j > 0 else float('-inf')
        b_right = b[j] if j < m else float('inf')

        if a_left <= b_right and b_left <= a_right:
            if (n + m) % 2 == 1:
                return float(max(a_left, b_left))
            return (max(a_left, b_left) + min(a_right, b_right)) / 2.0

        if a_left > b_right:
            high = i - 1         # too many of a on the left
        else:
            low = i + 1

    return 0.0                   # unreachable for valid input

