function findMedian(a, b) {
  // Search the shorter array so the forced cut j always lands inside b.
  if (a.length > b.length) [a, b] = [b, a];

  const n = a.length;
  const m = b.length;
  const half = Math.floor((n + m + 1) / 2);
  let low = 0;
  let high = n;

  while (low <= high) {
    const i = Math.floor((low + high) / 2);
    const j = half - i;

    const aLeft = i > 0 ? a[i - 1] : -Infinity;
    const aRight = i < n ? a[i] : Infinity;
    const bLeft = j > 0 ? b[j - 1] : -Infinity;
    const bRight = j < m ? b[j] : Infinity;

    if (aLeft <= bRight && bLeft <= aRight) {
      if ((n + m) % 2 === 1) return Math.max(aLeft, bLeft);
      return (Math.max(aLeft, bLeft) + Math.min(aRight, bRight)) / 2;
    }

    if (aLeft > bRight) high = i - 1;
    else low = i + 1;
  }

  return 0;
}

double findMedian(std::vector<long long> a, std::vector<long long> b) {
    if (a.size() > b.size()) std::swap(a, b);

    const long long n = (long long)a.size();
    const long long m = (long long)b.size();
    const long long half = (n + m + 1) / 2;

    // Integer sentinels rather than floating infinities, so no value in range
    // can ever compare equal to one of them.
    const long long NEG = std::numeric_limits<long long>::min();
    const long long POS = std::numeric_limits<long long>::max();

    long long low = 0, high = n;
    while (low <= high) {
        long long i = (low + high) / 2;
        long long j = half - i;

        long long aLeft  = (i > 0) ? a[(std::size_t)(i - 1)] : NEG;
        long long aRight = (i < n) ? a[(std::size_t)i]       : POS;
        long long bLeft  = (j > 0) ? b[(std::size_t)(j - 1)] : NEG;
        long long bRight = (j < m) ? b[(std::size_t)j]       : POS;

        if (aLeft <= bRight && bLeft <= aRight) {
            if ((n + m) % 2 == 1) return (double)std::max(aLeft, bLeft);
            return ((double)std::max(aLeft, bLeft) +
                    (double)std::min(aRight, bRight)) / 2.0;
        }

        if (aLeft > bRight) high = i - 1;
        else low = i + 1;
    }

    return 0.0;
}
